#!/usr/bin/env python3
"""Single-file bring-up build of ohmarchy-oseasy-agent. GENERATED by make-bundle.py — do not edit."""
import glob, os, sys, time, struct

# ===== frame.py =====
"""OSEasy guest-agent link frame codec.

Wire format reverse-engineered from the vendor's Windows agent
(agent_service.exe, COMMON::LinkBase::ReceiveMessage); see
docs/oseasy-agent-protocol.md section B. This is a clean-room, interoperable
re-implementation — it bypasses no authentication and copies no vendor code.

A message on the vioserial link is a 7-byte header followed by the body:

    offset  size  field         encoding
    0       4     payloadSize   uint32 big-endian   (sanity: payloadSize-1 <= 0x0FFFFFFF)
    4       1     msgType       uint8               (0..3)
    5       2     checksum      uint16 big-endian
    7       N     body          payloadSize bytes   (serialized Guest.protobuf.link message)

The checksum is a plain additive sum of the five header bytes before it:

    checksum = (h[0] + h[1] + h[2] + h[3] + h[4]) & 0xFFFF
"""


HEADER_LEN = 7
MAX_PAYLOAD = 0x0FFFFFFF


class ChecksumError(ValueError):
    pass


def header_checksum(first5: bytes) -> int:
    """16-bit additive checksum of the first five header bytes."""
    if len(first5) < 5:
        raise ValueError("need at least 5 header bytes")
    return sum(first5[:5]) & 0xFFFF


def encode(msg_type: int, body: bytes) -> bytes:
    """Build a full frame (header + body) for a body already serialized."""
    if not 0 <= msg_type <= 3:
        raise ValueError("msg_type must be 0..3")
    size = len(body)
    if size > MAX_PAYLOAD:
        raise ValueError("body larger than MAX_PAYLOAD")
    head5 = struct.pack(">IB", size, msg_type)  # 4-byte size + 1-byte type
    cksum = header_checksum(head5)
    return head5 + struct.pack(">H", cksum) + body


def decode_header(hdr: bytes):
    """Validate a 7-byte header; return (payloadSize, msgType)."""
    if len(hdr) != HEADER_LEN:
        raise ValueError("header must be exactly 7 bytes")
    size, msg_type = struct.unpack(">IB", hdr[:5])
    cksum = struct.unpack(">H", hdr[5:7])[0]
    want = header_checksum(hdr[:5])
    if cksum != want:
        raise ChecksumError("checksum mismatch: got 0x%04x want 0x%04x" % (cksum, want))
    if size > 0 and (size - 1) > MAX_PAYLOAD:
        raise ValueError("payloadSize out of range: %d" % size)
    return size, msg_type


def read_frame(recv_exactly):
    """Read one frame using a `recv_exactly(n) -> bytes` callable.

    Returns (msgType, body). Raises ChecksumError / ValueError on a bad frame.
    """
    hdr = recv_exactly(HEADER_LEN)
    size, msg_type = decode_header(hdr)
    body = recv_exactly(size) if size else b""
    return msg_type, body

# ===== pb.py =====
"""Minimal protobuf codec for the Guest.protobuf.link messages we need.

Hand-rolled so the agent has no external dependency (the Omarchy guest image
only needs python3). Schema reverse-engineered from the vendor agent's embedded
FileDescriptorProtos; see docs/oseasy-agent-protocol.md section A.

Messages (field numbers / proto types):
  Handshake { connectionMode:1 string, clientName:2 string, authString:3 bytes }
  Call      { callID:1 uint32, methodID:2 uint32, parameters:3 bytes, async:4 bool }
  Result    { callID:1 uint32, response:2 bytes, errorCode:3 int32 }
  CapInfo   { cap:1 int32, status:2 int32 }
  CapSet    { capInfo:1 repeated CapInfo }

Wire types used: 0 = varint (int32/uint32/bool), 2 = length-delimited (string/bytes/message).
"""

# ---- primitives ----

def write_varint(n: int) -> bytes:
    if n < 0:
        n &= (1 << 64) - 1  # two's-complement for negative int32/int64
    out = bytearray()
    while True:
        b = n & 0x7F
        n >>= 7
        if n:
            out.append(b | 0x80)
        else:
            out.append(b)
            return bytes(out)


def read_varint(buf: bytes, pos: int):
    shift = 0
    result = 0
    while True:
        b = buf[pos]
        pos += 1
        result |= (b & 0x7F) << shift
        if not (b & 0x80):
            return result, pos
        shift += 7


def _tag(field: int, wire: int) -> bytes:
    return write_varint((field << 3) | wire)


def field_varint(field: int, value: int) -> bytes:
    return _tag(field, 0) + write_varint(value)


def field_bytes(field: int, value: bytes) -> bytes:
    return _tag(field, 2) + write_varint(len(value)) + value


def field_string(field: int, value: str) -> bytes:
    return field_bytes(field, value.encode("utf-8"))


def parse_fields(buf: bytes):
    """Yield (field_number, wire_type, value) for each field.

    value is an int for varint fields, bytes for length-delimited fields.
    """
    pos = 0
    n = len(buf)
    while pos < n:
        tag, pos = read_varint(buf, pos)
        field = tag >> 3
        wire = tag & 7
        if wire == 0:
            value, pos = read_varint(buf, pos)
        elif wire == 2:
            length, pos = read_varint(buf, pos)
            value = buf[pos:pos + length]
            pos += length
        elif wire == 5:
            value = buf[pos:pos + 4]
            pos += 4
        elif wire == 1:
            value = buf[pos:pos + 8]
            pos += 8
        else:
            raise ValueError("unsupported wire type %d" % wire)
        yield field, wire, value


# ---- messages ----

def encode_handshake(connection_mode: str, client_name: str) -> bytes:
    # authString (field 3) deliberately omitted: it is an optional field and we
    # do not attempt the vendor's authstring handshake (see agent-protocol doc).
    return field_string(1, connection_mode) + field_string(2, client_name)


def encode_call(call_id: int, method_id: int, parameters: bytes = b"", async_: bool = False) -> bytes:
    out = field_varint(1, call_id) + field_varint(2, method_id)
    if parameters:
        out += field_bytes(3, parameters)
    if async_:
        out += field_varint(4, 1)
    return out


def decode_call(buf: bytes) -> dict:
    out = {"callID": 0, "methodID": 0, "parameters": b"", "async": False}
    for field, _wire, value in parse_fields(buf):
        if field == 1:
            out["callID"] = value
        elif field == 2:
            out["methodID"] = value
        elif field == 3:
            out["parameters"] = value
        elif field == 4:
            out["async"] = bool(value)
    return out


def encode_result(call_id: int, response: bytes = b"", error_code: int = 0) -> bytes:
    out = field_varint(1, call_id)
    if response:
        out += field_bytes(2, response)
    if error_code:
        out += field_varint(3, error_code)
    return out


def decode_result(buf: bytes) -> dict:
    out = {"callID": 0, "response": b"", "errorCode": 0}
    for field, _wire, value in parse_fields(buf):
        if field == 1:
            out["callID"] = value
        elif field == 2:
            out["response"] = value
        elif field == 3:
            out["errorCode"] = value
    return out


def encode_capinfo(cap: int, status: int) -> bytes:
    out = b""
    if cap:
        out += field_varint(1, cap)
    if status:
        out += field_varint(2, status)
    return out


def encode_capset(cap_infos) -> bytes:
    # repeated CapInfo capInfo = 1;
    return b"".join(field_bytes(1, encode_capinfo(c, s)) for (c, s) in cap_infos)

# ===== agent.py =====
#!/usr/bin/env python3
"""Minimal, interoperable Linux guest agent for OSEasy (prototype).

Goal: make OSEasy treat a Linux VM as "installed / can power on" instead of only
offering 再次安装 (which wipes the disk). It does this by speaking OSEasy's own
guest-agent link protocol (virtio-serial + length/checksum framing + protobuf
RPC), reverse-engineered in docs/oseasy-agent-protocol.md.

Scope / ethics (set with the supervisor):
  * Interop only. We DO NOT send `authString` and DO NOT attempt the vendor's
    "authstring handshake"; `authString` is an optional field. If OSEasy refuses
    the plain handshake or demands authString, that is an authentication barrier
    — STOP and record it in docs/oseasy-vendor-request.md; do not bypass it.
  * `clientName` is our own honest name ("ohmarchy-linux-agent"); we never
    impersonate the vendor's agent.

Status: the frame codec (section B) and message schema (section A) are known and
unit-tested. Three things are only resolvable on-device and are marked TODO:
  (1) which virtio-serial port carries the `link` service,
  (2) the `connectionMode` string value and the handshake `msgType`,
  (3) the method-id registry (keepalive / install-complete / CapInfo query).
The agent logs every inbound frame so the bring-up run can fill these in.
"""



CLIENT_NAME = "ohmarchy-linux-agent"

# TODO(on-device): confirmed handshake parameters. These are placeholders; the
# bring-up run determines them from what OSEasy accepts / sends.
CONNECTION_MODE = os.environ.get("OSEASY_CONN_MODE", "command")
HANDSHAKE_MSGTYPE = int(os.environ.get("OSEASY_HS_MSGTYPE", "0"))
DATA_MSGTYPE = int(os.environ.get("OSEASY_DATA_MSGTYPE", "0"))
KEEPALIVE_SECONDS = int(os.environ.get("OSEASY_KEEPALIVE", "5"))

# Host-side virtio-serial port names seen in the StratoVirt command line. The
# right one for the main link still needs on-device confirmation.
PORT_NAME_CANDIDATES = [
    "winbox_serial0", "winbox_serial1",
    "additions_vioser0", "additions_vioser1",
]


def log(*a):
    print("[ohmarchy-oseasy-agent]", *a, file=sys.stderr, flush=True)


def find_vport(candidates=PORT_NAME_CANDIDATES):
    """Return the /dev/vportNpX whose /sys name matches a candidate, else None."""
    found = {}
    for name_path in glob.glob("/sys/class/virtio-ports/*/name"):
        try:
            with open(name_path) as fh:
                nm = fh.read().strip()
        except OSError:
            continue
        port = os.path.basename(os.path.dirname(name_path))  # e.g. vport2p1
        found[nm] = "/dev/" + port
    log("virtio-ports present:", found)
    for cand in candidates:
        if cand in found:
            return found[cand]
    return None


class Link:
    def __init__(self, path):
        self.fd = os.open(path, os.O_RDWR)
        log("opened", path)

    def recv_exactly(self, n):
        buf = b""
        while len(buf) < n:
            chunk = os.read(self.fd, n - len(buf))
            if not chunk:
                time.sleep(0.05)
                continue
            buf += chunk
        return buf

    def send(self, msg_type, body):
        os.write(self.fd, encode(msg_type, body))

    def close(self):
        try:
            os.close(self.fd)
        except OSError:
            pass


def do_handshake(link):
    body = encode_handshake(CONNECTION_MODE, CLIENT_NAME)
    log("sending handshake: connectionMode=%r clientName=%r (no authString)"
        % (CONNECTION_MODE, CLIENT_NAME))
    link.send(HANDSHAKE_MSGTYPE, body)


def serve(link):
    last_keepalive = 0.0
    while True:
        # keepalive heartbeat (methodID TODO; structure is a link.Call)
        now = time.time()
        if now - last_keepalive >= KEEPALIVE_SECONDS:
            # TODO(on-device): real keepalive methodID. Logged so bring-up can
            # observe whether OSEasy expects one and what id it uses.
            last_keepalive = now

        msg_type, data = read_frame(link.recv_exactly)
        call = decode_call(data)
        log("RX frame type=%d len=%d call=%s" % (msg_type, len(data), call))
        # TODO(on-device): dispatch by call["methodID"] — reply to a CapInfo
        # query with our CapSet, ack keepalive, etc. Until the method registry
        # is known we only observe.


def main():
    port = find_vport()
    if port is None:
        log("no matching virtio-serial port; set PORT_NAME_CANDIDATES after"
            " checking /sys/class/virtio-ports/*/name on the guest")
        return 1
    link = Link(port)
    try:
        do_handshake(link)
        serve(link)
    finally:
        link.close()
    return 0


if __name__ == "__main__":
    sys.exit(main())
